# Apply the demo-inferred offsets on a 10x10 (0-based) board, clipping off-board cells.
markers = {1:(2,1), 2:(6,7), 6:(7,5), 3:(7,9)}
offsets = {1:(-1,2), 2:(0,-4), 6:(-6,0), 3:(3,0)}
N=10
cells = {p:c for c,p in markers.items()}
for color,(r,c) in markers.items():
    dr,dc=offsets[color]; end=(r+dr,c+dc)
    # Offsets trace axis-aligned path; these offsets each have only one nonzero component except color 1.
    path=[]
    if dr and dc:
        # inferred color-1 route: horizontal first, then vertical
        path += [(r,c+k*(1 if dc>0 else -1)) for k in range(1,abs(dc)+1)]
        path += [(r+k*(1 if dr>0 else -1),c+dc) for k in range(1,abs(dr)+1)]
    elif dr:
        path += [(r+k*(1 if dr>0 else -1),c) for k in range(1,abs(dr)+1)]
    elif dc:
        path += [(r,c+k*(1 if dc>0 else -1)) for k in range(1,abs(dc)+1)]
    for p in path:
        if 0<=p[0]<N and 0<=p[1]<N and p != end:
            cells[p]=5
    if 0<=end[0]<N and 0<=end[1]<N:
        cells[end]=color
# overlap of line paths is a crossing; explicitly assign 4 and diagonal ray down-left
cells[(6,5)] = 4
for d in range(1, min(N-6, 5)+1):
    p=(6+d,5-d)
    if 0<=p[0]<N and 0<=p[1]<N: cells[p]=4
print('cells=', sorted((color,*p) for p,color in cells.items()))
print('grid:')
for r in range(N): print(' '.join(str(cells.get((r,c),0)) for c in range(N)))

